package com.yeyamo_mobile.api.recommendation_service.infrastructure.messaging;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.recommendation_service.application.RecommendationProjectionService;import com.yeyamo_mobile.api.recommendation_service.domain.Candidate;
class RecommendationEventConsumerTest{private final ObjectMapper mapper=new ObjectMapper();@Test void projectsPublishedCatalogAsset()throws Exception{var service=mock(RecommendationProjectionService.class);var receipts=mock(ProcessedEventRepository.class);var consumer=new RecommendationEventConsumer(mapper,service,receipts);consumer.catalog(event("catalog.asset.status_changed","{\"assetId\":\"1\",\"type\":\"PLACE\",\"name\":\"Plage\",\"status\":\"PUBLISHED\",\"latitude\":4,\"longitude\":9}"));var captor=ArgumentCaptor.forClass(Candidate.class);verify(service).candidate(captor.capture());assertTrue(captor.getValue().active());assertEquals("catalog:1",captor.getValue().sourceId());verify(receipts).save(any());}@Test void convertsInteractionIntoPopularityAndHistory()throws Exception{var service=mock(RecommendationProjectionService.class);var consumer=new RecommendationEventConsumer(mapper,service,mock(ProcessedEventRepository.class));consumer.interaction(event("interaction.favorite.added","{\"postId\":\"42\",\"userId\":\"u1\"}"));verify(service).popularity("content:42",3);verify(service).signal("u1","content:42",3);}@Test void projectsUserPreferences()throws Exception{var service=mock(RecommendationProjectionService.class);var consumer=new RecommendationEventConsumer(mapper,service,mock(ProcessedEventRepository.class));consumer.user(event("profile.preferences_updated","{\"authUserId\":\"u1\",\"preferredRegionId\":\"10\",\"language\":\"FRENCH\",\"locationSharingEnabled\":true}"));verify(service).preference("u1","10","FRENCH",true);}@Test void duplicateEventIsIgnored()throws Exception{UUID id=UUID.randomUUID();var service=mock(RecommendationProjectionService.class);var receipts=mock(ProcessedEventRepository.class);when(receipts.existsById(id)).thenReturn(true);new RecommendationEventConsumer(mapper,service,receipts).feed(event(id,"feed.metrics.updated","{\"postId\":\"1\"}"));verifyNoInteractions(service);verify(receipts,never()).save(any());}private String event(String type,String payload){return event(UUID.randomUUID(),type,payload);}private String event(UUID id,String type,String payload){return"{\"eventId\":\""+id+"\",\"eventType\":\""+type+"\",\"eventVersion\":1,\"payload\":"+payload+"}";}}
